const getAgreements = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`/subcontractor-agreements/${route.params.agreement_id}`);
    const item = response.data;

    const totalCost = parseFloat(item.total_quantity) * parseFloat(item.rate);
    let cumulativePaid = 0;

    // Calculate total archived amount (total payments made)
    const totalArchivedAmount = (item.payments || []).reduce((sum, p) => sum + p.quantity, 0);

    // Calculate archived quantity (work done)
    const totalArchivedQty = (item.payments || []).reduce((sum, p) => {
      const workQty = Number(p.quantity) / Number(item.rate);
      return sum + workQty;
    }, 0);

    // Calculate pending amount
    const pendingArchivedQty = parseFloat(item.total_quantity) - totalArchivedQty;
    const pendingArchivedAmount = pendingArchivedQty * parseFloat(item.rate);

    const paymentsWithRemaining = (item.payments || []).map((p, idx) => {
      cumulativePaid += p.quantity;
      const remaining = totalCost - cumulativePaid;
      const workQty = Number(p.quantity) / Number(item.rate);
      return {
        ...p,
        sno: idx + 1,
        voucher_no: p.order_id,
        payment: formatNumber(p.quantity),
        date: new Date(p.created_at).toLocaleDateString(),
        balance: formatNumber(remaining === 0 ? p.quantity : remaining),
        description: p.description || ' ',
        amount: workQty.toFixed(2) || ' '
      };
    });

    const totalPaid = totalArchivedAmount;
    const payable = totalCost - totalPaid;
    const remainingAmount = totalCost - payable;
    const balance = remainingAmount === 0 ? payable : remainingAmount;

    agreements.value = {
      ...item,
      quantity: item.quantity, 
      revised_quantity:item.revised_quantity,
      total_quantity:item.total_quantity,
